cd /private/tmp/live-spec-integrate-slimdown/wt && python3 -c "
import json
d=json.load(open('guardrails/language-rules.json'))
rules=d['rules']
print('total rules', len(rules))
for r in rules:
    a=r.get('armed',[])
    if any(x in ('session-stop-hook','session-prompt-hook') for x in a):
        cw=[]
        for k,v in (r.get('catchers') or {}).items():
            if isinstance(v,dict) and 'where' in v: cw.append(k+':'+v.get('status','')+':'+v['where'][:90])
        print(r.get('id'), '|', r.get('status'), '|', a, '|', r.get('name','')[:60])
        for c in cw: print('    ', c)
"

